#!/usr/bin/env node
/**
 * Bundle the user documentation (docs/**.md) into a TypeScript module Rocksy
 * can search at run time (`app_docs_search`, src/main/assistant/appDocsSearch.ts).
 *
 * Generated rather than read from disk because the docs folder ships in
 * neither the Electron package nor the daemon's image — only `dist/` does —
 * and a module compiled into `dist/` reaches both with no packaging rule to
 * forget. The output is checked in, and
 * `src/__tests__/regressions/app-docs-bundle.test.ts` fails when it no longer
 * matches docs/, so an edited page cannot silently leave Rocksy behind.
 *
 *   node scripts/bundle-docs.js          regenerate
 *   node scripts/bundle-docs.js --check  exit 1 if the bundle is stale
 */
const fs = require("fs");
const path = require("path");

const ROOT = path.resolve(__dirname, "..");
const DOCS = path.join(ROOT, "docs");
const OUT = path.join(
  ROOT,
  "src",
  "main",
  "assistant",
  "docsCorpus.generated.ts",
);
/** Folders under docs/ that hold no prose: VitePress config, images. */
const SKIP_DIRS = new Set([
  ".vitepress",
  "public",
  "screenshots",
  "node_modules",
]);

function collect(dir) {
  const out = [];
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    if (entry.isDirectory()) {
      if (!SKIP_DIRS.has(entry.name))
        out.push(...collect(path.join(dir, entry.name)));
    } else if (entry.name.endsWith(".md")) {
      out.push(path.join(dir, entry.name));
    }
  }
  return out;
}

function titleOf(markdown, fallback) {
  const m = /^#\s+(.+)$/m.exec(markdown);
  return m ? m[1].trim() : fallback;
}

/** Drop VitePress frontmatter; Rocksy needs the prose, not the page config. */
function stripFrontmatter(markdown) {
  return markdown.replace(/^---\n[\s\S]*?\n---\n/, "");
}

/**
 * A page's text as Rocksy gets it. Line endings first: on a Windows checkout
 * the frontmatter is CRLF and stripFrontmatter's `\n` pattern never matches it.
 */
function pageContent(raw) {
  return stripFrontmatter(raw.replace(/\r\n/g, "\n"));
}

function render() {
  const pages = collect(DOCS)
    .map((file) => {
      const rel = path.relative(DOCS, file).split(path.sep).join("/");
      const content = pageContent(fs.readFileSync(file, "utf8"));
      return { path: rel, title: titleOf(content, rel), content };
    })
    .sort((a, b) => (a.path < b.path ? -1 : a.path > b.path ? 1 : 0));

  return (
    "// GENERATED by scripts/bundle-docs.js from docs/ — do not edit by hand.\n" +
    "// Regenerate with `node scripts/bundle-docs.js` after changing the docs.\n" +
    "\n" +
    "export interface DocsPage {\n" +
    '  /** Path under docs/, e.g. "app-reference/sync.md". */\n' +
    "  path: string;\n" +
    "  title: string;\n" +
    "  content: string;\n" +
    "}\n" +
    "\n" +
    `export const DOCS_PAGES: DocsPage[] = ${JSON.stringify(pages, null, 2)};\n`
  );
}

function main() {
  const next = render();
  if (process.argv.includes("--check")) {
    const current = fs.existsSync(OUT) ? fs.readFileSync(OUT, "utf8") : "";
    if (current !== next) {
      console.error(
        "docsCorpus.generated.ts is stale — run: node scripts/bundle-docs.js",
      );
      process.exit(1);
    }
  } else {
    fs.writeFileSync(OUT, next);
    console.log(`bundled ${DOCS} -> ${path.relative(ROOT, OUT)}`);
  }
}

if (require.main === module) main();

module.exports = { render, pageContent, OUT };
